# Let me try a more systematic search for a permutation that works
# with the initial grouping [0,1,2], [3,4,5], ..., [27,28,29]

import itertools
import random

G = 30
B = 10
K = 3

def check_permutation(pi):
    """Check if permutation pi works for 8 weeks"""
    # Build schedule
    schedule = [[0]*G for _ in range(8)]

    # Week 0: initial groups
    for i in range(B):
        for j in range(K):
            schedule[0][i*K + j] = i

    # Compute inverse
    inv_pi = [0]*G
    for p in range(G):
        inv_pi[pi[p]] = p

    # For weeks 1..7, apply pi^w
    # pi_neg_w = pi^{-w}
    pi_neg_w = list(range(G))
    for w in range(1, 8):
        # pi_neg_w = pi_neg_w composed with inv_pi
        pi_neg_w = [inv_pi[p] for p in pi_neg_w]
        for p in range(G):
            schedule[w][p] = pi_neg_w[p] // 3

    # Check
    used_pairs = set()
    for w in range(8):
        for g in range(B):
            members = [p for p in range(G) if schedule[w][p] == g]
            if len(members) != K:
                return False
            for i in range(len(members)):
                for j in range(i+1, len(members)):
                    pair = (min(members[i], members[j]), max(members[i], members[j]))
                    if pair in used_pairs:
                        return False
                    used_pairs.add(pair)
    return True

# Let me try permutations of the form pi(x) = a*x + b mod 30
# where gcd(a, 30) = 1

for a in [1, 7, 11, 13, 17, 19, 23, 29]:
    for b in range(30):
        pi = [(a*i + b) % 30 for i in range(30)]
        if check_permutation(pi):
            print(f"Found! a={a}, b={b}")
            break
    else:
        continue
    break
else:
    print("No linear permutation works")

