def check_permutation_with_init(pi, init_groups):
    """Check if permutation pi works with given initial groups"""
    G = 30
    B = 10
    K = 3
    schedule = [[0]*G for _ in range(8)]

    # Week 0
    for i in range(B):
        for p in init_groups[i]:
            schedule[0][p] = i

    inv_pi = [0]*G
    for p in range(G):
        inv_pi[pi[p]] = p

    pi_neg_w = list(range(G))
    for w in range(1, 8):
        pi_neg_w = [inv_pi[p] for p in pi_neg_w]
        for p in range(G):
            # Find which initial group pi_neg_w[p] belongs to
            for i in range(B):
                if pi_neg_w[p] in init_groups[i]:
                    schedule[w][p] = i
                    break

    used_pairs = set()
    for w in range(8):
        for g in range(B):
            members = [p for p in range(G) if schedule[w][p] == g]
            if len(members) != K:
                return False
            for i in range(len(members)):
                for j in range(i+1, len(members)):
                    pair = (min(members[i], members[j]), max(members[i], members[j]))
                    if pair in used_pairs:
                        return False
                    used_pairs.add(pair)
    return True

